#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1);
    vector<vector<int>> radj(n+1);
    vector<int> indeg(n+1,0), outdeg(n+1,0);

    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        outdeg[u]++;
        indeg[v]++;
    }

    // Try to find Hamiltonian path using randomized approach with restarts
    auto now = chrono::steady_clock::now;
    auto start_time = now();

    vector<int> best_path;

    mt19937 rng(42);

    // Adjacency set for O(1) lookup
    vector<unordered_set<int>> adj_set(n+1);
    for(int u=1;u<=n;u++) adj_set[u].insert(adj[u].begin(), adj[u].end());

    while(chrono::duration_cast<chrono::milliseconds>(now()-start_time).count() < 3500){
        // Random starting vertex
        int sv = rng()%n + 1;

        vector<bool> used(n+1, false);
        vector<int> path;
        path.reserve(n);
        path.push_back(sv);
        used[sv] = true;

        // Greedy extend with Warnsdorff heuristic
        while(true){
            int cur = path.back();
            int best = -1, best_score = INT_MAX;
            // Shuffle neighbors for randomness
            auto &nb = adj[cur];
            int cnt = 0;
            for(int v : nb){
                if(!used[v]){
                    // Count available out-neighbors of v
                    int sc = 0;
                    for(int w : adj[v]) if(!used[w]) sc++;
                    if(sc < best_score || (sc == best_score && (rng()&1))){
                        best_score = sc;
                        best = v;
                    }
                    cnt++;
                }
            }
            if(best == -1) break;
            path.push_back(best);
            used[best] = true;
        }

        // Try to extend from front too
        // Reverse: try prepending
        while(true){
            int cur = path.front();
            int best = -1, best_score = INT_MAX;
            for(int v : radj[cur]){
                if(!used[v]){
                    int sc = 0;
                    for(int w : radj[v]) if(!used[w]) sc++;
                    if(sc < best_score || (sc == best_score && (rng()&1))){
                        best_score = sc; best = v;
                    }
                }
            }
            if(best == -1) break;
            path.insert(path.begin(), best);
            used[best] = true;
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
        if((int)best_path.size() == n) break;
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++) cout << best_path[i] << " \n"[i+1==(int)best_path.size()];
}
